// -- Entry-path resolution ------------------------------------------------
// DripWebhook -> Verify JWT -> here        (public HTTP; auth enforced)
// Called by Master Router -> here          (sub-workflow; already trusted)
//
// $('DripWebhook') THROWS when that node did not run in this execution -- it
// does NOT return undefined, so `?.` and `||` cannot rescue it, and an
// Expression field cannot hold try/catch. Removing this try/catch breaks the
// Master Router sub-workflow path.
let webhookJson = null;
try {
  webhookJson = $('DripWebhook').first().json;
} catch (e) {
  // sub-workflow path -- DripWebhook never executed.
}

let item;
if (webhookJson) {
  // 'Verify JWT' runs with onError = continueRegularOutput, so a rejected
  // token arrives as data. Supabase returns the user object on success.
  // This endpoint is fire-and-forget (the caller only ever sees
  // 'Workflow was started'), so a failed execution is the right signal.
  const auth = $input.first().json || {};
  if (!auth.id) {
    throw new Error('Drip campaign aborted: unauthorized. A valid Supabase session token is required in the Authorization header.');
  }
  item = webhookJson;
} else {
  item = $input.first().json;
}

// -- Normalise the lead ---------------------------------------------------
// Invoked two ways: webhook POST puts data under .body, the Master Router
// passes it under .lead. The dashboard posts lead_email / lead_name; the
// Master Router passes email / name. Both vocabularies are accepted.
let lead;
if (item.lead) {
  lead = item.lead;                 // Master Router sub-workflow call
} else if (item.body) {
  lead = item.body;                 // raw webhook POST
} else {
  lead = item;                      // already flat
}

const clean = (v) => (v === undefined || v === null || v === false || v === '') ? null : String(v).trim();

// `lead` can legitimately be a non-object here: a manual run from the n8n
// editor hands this node an empty item, and Object.keys(null) throws a
// TypeError that n8n surfaces as a bare "Unknown error [line N]" -- which is
// how a guard doing its job came to look like a broken node.
const leadKeys = (lead && typeof lead === 'object') ? Object.keys(lead) : [];

const email = clean(lead && lead.email) || clean(lead && lead.lead_email);
if (!email) {
  // This is not a fault. It is the node refusing to start a seven-day email
  // sequence aimed at nobody. Say which of the two situations it is, because
  // one needs fixing and the other is just the editor's Execute button.
  if (leadKeys.length === 0) {
    throw new Error(
      'Drip campaign not started: no lead was supplied. This workflow is ' +
      'triggered by a webhook (POST /webhook/lead-trigger) or called by the ' +
      'Master Router -- pressing Execute in the editor runs it with no input, ' +
      'so there is no lead to enrol and nothing was sent. To test it from the ' +
      'editor, pin data on this node with an email address on it.');
  }
  throw new Error(
    'Drip campaign not started: a lead arrived but carried no email address. ' +
    'Keys received: ' + leadKeys.join(', ') + '. Accepted field names are ' +
    'email or lead_email.');
}

return [{
  json: {
    name: clean(lead.name) || clean(lead.lead_name) || 'there',
    email: email,
    phone: clean(lead.phone) || clean(lead.whatsapp),
    vehicle_interest: clean(lead.vehicle_interest) || clean(lead.vehicleInterest) || clean(lead.message) || 'a vehicle'
  }
}];

// Delivery Report - verify every claim the next node is about to make.
// The upstream sends run with onError:'continueRegularOutput'. A failure there
// is not an exception: n8n emits an item shaped { error: ... } on the main
// output and the run stays green. Nothing downstream ever looked at it, so the
// row written next asserted a send that may never have landed.
// The swallow is deliberate and stays. Only the unconditional claim goes.
// Only claim the WhatsApp legs when this lead actually took them. Both
// 'Has WhatsApp? (Day 1)' and 'Has WhatsApp? (Day 5)' branch on
// !!$('Normalize Lead Input').first().json.phone, so a lead with no phone
// legitimately never runs those nodes - claiming them unconditionally would
// report a false drop for every email-only lead.
const lead = (() => { try { return $('Normalize Lead Input').first().json || {}; }
                      catch (e) { return {}; } })();
const hasWhatsApp = !!lead.phone;

const CLAIMED = [
  { node: 'Email: Welcome (Gmail)', what: 'Day 1 welcome email', critical: true },
  { node: 'Log Welcome Email', what: 'Day 1 email communication_logs row', critical: false },
  { node: 'Email: Follow Up (Gmail)', what: 'Day 3 follow-up email', critical: true },
  { node: 'Log Follow Up Email', what: 'Day 3 email communication_logs row', critical: false },
  { node: 'Email: Final Offer (Gmail)', what: 'Day 7 final-offer email', critical: true },
  { node: 'Log Final Offer Email', what: 'Day 7 email communication_logs row', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);

if (hasWhatsApp) {
  results.push(check({ node: 'WhatsApp: Welcome',       what: 'Day 1 WhatsApp welcome',                 critical: true }));
  results.push(check({ node: 'Log WhatsApp Welcome',    what: 'Day 1 WhatsApp communication_logs row',  critical: false }));
  results.push(check({ node: 'WhatsApp: Check-in',      what: 'Day 5 WhatsApp check-in',                critical: true }));
  results.push(check({ node: 'Log WhatsApp Check-in',   what: 'Day 5 WhatsApp communication_logs row',  critical: false }));
}

const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' \u2014 ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} }];

